// EZB-Referenzkurs: 1 Euro = x US-Dollar. Gespeichert wird 1 US-Dollar = 1/x Euro.
const xml = String($input.first().json.xml || '');
const usd = xml.match(/currency=['"]USD['"]\s+rate=['"]([0-9.]+)['"]/);
const tag = xml.match(/time=['"]([0-9]{4}-[0-9]{2}-[0-9]{2})['"]/);
if (!usd || !tag) throw new Error('EZB-Kurs nicht gefunden.');
const eur = 1 / Number(usd[1]);
if (!(eur > 0.5 && eur < 1.5)) throw new Error('EZB-Kurs unplausibel: ' + usd[1]);
return [{ json: { usd_eur: eur.toFixed(4), stand: tag[1], eur_usd: usd[1] } }];

